void ccsds_PI_build_space_packet( const asn1SccSpace_Packet *in, const asn1SccPus_Packet_Bytes *IN_DATA, asn1SccSpace_Packet_Bytes *out ){
    //uint8_t data = IN_DATA->arr[0];

    // for(int i = 0; i < IN_DATA->nCount; i++){
    //     in->data.arr[i] = IN_DATA->arr[i];
    // }

    uint16_t i = 0; // Index counter

    uint16_t SPPacketID = 0;
    //Need to cast uint8s to uint16s as shiffting out of the size of 8 bits
    SPPacketID = (((uint16_t)in->packet_version_number & 0x07) << 13) | (((uint16_t)in->packet_type & 0x01) << 12) | (((uint16_t)in->secondary_header_flag & 0x01) << 11) | ((uint16_t)in->apid & 0x07FFu);

    out->arr[i++] = (uint8_t)(SPPacketID >> 8);
    out->arr[i++] = (uint8_t)(SPPacketID & 0xFF);

    uint16_t PacketSequenceControl = 0;
    PacketSequenceControl = (((uint16_t)in->sequence_flags & 0x03) << 14) | (((uint16_t)in->packet_sequence_count & 0x3FFF));

    out->arr[i++] = (uint8_t)(PacketSequenceControl >> 8);
    out->arr[i++] = (uint8_t)(PacketSequenceControl & 0xFF);

    //Packet length - 1
    out->arr[i++] = (uint8_t)( (in->packet_data_length - 1) >> 8);  //TTemp FIx
    out->arr[i++] = (uint8_t)( (in->packet_data_length - 1) & 0xFF);

    uint8_t data_byte_counter = 0;
    for(data_byte_counter = 0; data_byte_counter < (in->packet_data_length ); data_byte_counter++){
        out->arr[i++] = IN_DATA->arr[data_byte_counter];
    }

    // asn1SccCrc16 crc = 0;
    // ccsds_RI_SP_CRC(out, &crc);
    // in->space_packet_crc16 = crc;

    out->nCount = i;                     // before the CRC call
    asn1SccCrc16 crc = 0;
    ccsds_RI_SP_CRC(out, &crc);

    out->arr[i++] = (uint8_t)(crc >> 8);
    out->arr[i++] = (uint8_t)(crc & 0xFF);
    out->nCount = i;                     // after appending the CRC

    // asn1SccT_UInt8 byteBuff;
    // for (int n = 0; n < out->nCount + 2; n++) {
    //     byteBuff = (asn1SccT_UInt8)out->arr[n];
    //     ccsds_RI_uart_byte_tx(&byteBuff);
    // }
    ccsds_RI_encode_bytes(out);



}
